	.text
	.even
	.globl	_nucleus
	.globl	_start
	.globl	___reltab
	.globl	_OSSyscallInit

########################################################################
# _start: compute base, apply relocs and call C nucleus() function
########################################################################

_start:	mov	pc,	r5
	sub	$012,	r5

	mov	r0,	___sector_buffer
	mov	r1,	___schedule
	mov	r2,	___nextday
	mov	r3,	___emttbl
	mov	r4,	___top

	# relocate the nucleus using the ___reltab generated by lsi-ld
	mov	$___reltab,r0
	add	r5,	r0	# r5 = reltab

	mov	r5,	r4
	mov	___top,	r1
	sub	r0,	r1
	add	r1,	r4

	mov	r0,	r1

	mov	(r0)+,	r2	# r2 = reloc count
1:	mov	(r0)+,	r3	# tmp = *(reloc++)
	add	r5,	r3	# tmp += relbase
	add	r4,	(r3)	# *tmp += relbase
	sob	r2,	1b

	# move nucleus to strip it from crt0 code and relocs
	mov	$_end,	___relbase
	mov	r1,	r0	# r0 = original reltab
	mov	___top,	r1	# r1 = top

	mov	r0,	r2
	sub	r5,	r2
	asr	r2		# r2 = (reltab - relbase) / 2

2:	mov	-(r0),	-(r1)	# move nucleus back in memory
	sob	r2,	2b
	mov	$_nucleus,r0	# this is already reloc'd now
_end:	jmp	(r0)		# jump to _nucleus

	.data
	.even
	.globl	___relbase
	.globl	___top
	.globl	___sector_buffer
	.globl	___schedule
	.globl	___nextday
	.globl	___emttbl
___relbase:
	.word	0
___top:
	.word	0
___sector_buffer:
	.word	0
___schedule:
	.word	0
___nextday:
	.word	0
___emttbl:
	.word	0
